package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class PerformanceCalibrationPermissionGuard{public static final String FEATURE="primehr.performance-calibration";private final AdministrativeAuthorizationClient client;public PerformanceCalibrationPermissionGuard(AdministrativeAuthorizationClient client){this.client=client;}public void require(PrimeHrAction action,String token){EffectiveFeaturePermission p=client.resolve(FEATURE,token);boolean allowed=p.administrator()||p.canAccess()&&switch(action){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case SUBMIT->p.canSubmit();case APPROVE->p.canApprove();case FINALIZE->p.canFinalize();default->false;};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Agency-wide performance calibration permission is required");}}
